jordan (sdk): sending concise samples now. Python: async resume pattern.

```python
# python: async resume example
from redwood import Client, TransientError
c = Client()

async def pages(prompt):
  async for s in c.stream_responses(model="open-3", input=prompt):
    try:
      async for p in s.paginate():
        yield p
    except TransientError:
      token = getattr(s, "retry_token", None)
      cursor = await c.get_cursor_from_retry(token)
      async for p in c.resume_pages(cursor):
        yield p
```

jordan (sdk): TypeScript: iterator + resume.

```ts
// ts: iterator + resume
import Redwood from '@redwood/inference'
const client = new Redwood()

export async function* pagesWithRetry(prompt: string) {
  for await (const s of client.streamResponses({ model: 'open-3', input: prompt })) {
    try {
      for await (const p of s.paginate()) yield p
    } catch {
      const token = (s as any).retryToken
      const cursor = await client.getCursorFromRetry(token)
      for await (const p of client.resumePages(cursor)) yield p
    }
  }
}
```

jordan (sdk): Go: resume stream pattern (Go SDK uses ResumeStream).

```go
// go: resume stream
package examples
import (
  "context"
  rw "github/redwood-inference/go-sdk"
)

func StreamWithRetry(ctx context.Context, prompt string) <-chan rw.Page {
  out := make(chan rw.Page)
  go func() {
    defer close(out)
    c := rw.NewClient()
    st, _ := c.StreamResponses(ctx, rw.StreamParams{Model: "open-3", Input: prompt})
    for st.Next() {
      pages, err := st.Pages()
      if err != nil {
        token, _ := st.RetryToken()
        cursor, _ := c.GetCursorFromRetry(ctx, token)
        resumed := c.ResumeStream(ctx, cursor)
        for resumed.Next() {
          for _, p := range resumed.Pages() { out <- p }
        }
        return
      }
      for _, p := range pages { out <- p }
    }
  }()
  return out
}
```

